package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.OriginTypeVO;

class OriginTypeValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of origin type of observed source")
  void test_origin_type_value_holder_assign_plain_value() {
    Object holder = new Object();
    OriginTypeValueHolder<Object> value = new OriginTypeValueHolder<>(holder);
    Assertions.assertSame(holder, value.originType("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getOriginTypeValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getOriginType().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of origin type of observed source")
  void test_origin_type_value_holder_assign_value_object() {
    Object holder = new Object();
    OriginTypeValueHolder<Object> value = new OriginTypeValueHolder<>(holder);
    OriginTypeVO vo = OriginTypeVO.from("one");
    Assertions.assertFalse(value.getOriginTypeValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.originType(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getOriginTypeValue().orElseThrow());
    Assertions.assertSame(holder, value.originType(Optional.empty()));
    Assertions.assertFalse(value.getOriginTypeValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.originType(Optional.of(vo)));
    Assertions.assertSame(vo, value.getOriginTypeValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of origin type of observed source against the original")
  void test_origin_type_value_holder_read() {
    Object holder = new Object();
    OriginTypeValueHolder<Object> value = new OriginTypeValueHolder<>(holder);
    OriginTypeVO vo = OriginTypeVO.from("one");
    OriginTypeVO other = OriginTypeVO.from("one");
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getOriginTypeValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readOriginType(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readOriginType(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.originType(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readOriginType(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readOriginType(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of origin type of observed source")
  void test_origin_type_value_holder_unset() {
    Object holder = new Object();
    OriginTypeValueHolder<Object> value = new OriginTypeValueHolder<>(holder);
    OriginTypeVO vo = OriginTypeVO.from("one");
    value.originType(vo);
    Assertions.assertSame(holder, value.unsetOriginTypeIfMatches("originType_other"));
    Assertions.assertTrue(value.getOriginTypeValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetOriginTypeIfMatches("originType"));
    Assertions.assertFalse(value.getOriginTypeValue().isPresent(),
        "The field name must clear the value");
    value.originType(vo);
    Assertions.assertSame(holder, value.unsetOriginType());
    Assertions.assertFalse(value.getOriginTypeValue().isPresent(), "Unset must clear the value");
  }
}
